# Validate inputs
for arr in (logp_with_result, logp_call_only, logp_no_call):
    if arr.ndim != 2:
        raise ValueError("All log probability matrices must be 2D")
    if arr.size == 0:
        raise ValueError("Empty matrices are not allowed")
    if not np.isfinite(arr).all():
        raise ValueError("All values must be finite")
    if (arr > 0).any():
        raise ValueError("All values must be nonpositive")
if not (logp_with_result.shape == logp_call_only.shape == logp_no_call.shape):
    raise ValueError("All matrices must have the same shape")
if not (np.isfinite(tau_filter) and tau_filter >= 0):
    raise ValueError("tau_filter must be a finite nonnegative number")

s_with = np.sum(logp_with_result, axis=1)
s_call = np.sum(logp_call_only, axis=1)
s_no = np.sum(logp_no_call, axis=1)

keep = (s_with - s_no > tau_filter) & (s_call - s_no <= tau_filter)
margins = s_with - s_no

return keep, margins
